import { expect, test, uniqueName } from "../../fixtures";

test("submitting with missing documents lists what is missing", { tag: "@REV-02" }, async ({ apiAs }) => {
  // Arrange: a draft vendor whose only document is an extracted W-9
  const member = await apiAs("member");
  const created = await member.post("/api/vendors", {
    data: { name: uniqueName("Harborline"), category: "services", contact_email: "ops@harborline.example" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = (await created.json()) as { id: string };

  const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "w9",
      file: {
        name: "w9.txt",
        mimeType: "text/plain",
        buffer: Buffer.from("Legal Name: Acme\nTax ID: 123456789\n"),
      },
    },
  });
  expect(upload.status(), await upload.text()).toBe(201);
  const document = (await upload.json()) as { id: string };

  // Extraction runs in the background; wait until the W-9 has been extracted.
  await expect
    .poll(async () => {
      const res = await member.get(`/api/documents/${document.id}`);
      return ((await res.json()) as { status: string }).status;
    }, { timeout: 15_000 })
    .toBe("extracted");

  // Act
  const response = await member.post(`/api/vendors/${vendor.id}/submit`);

  // Assert
  expect(response.status(), await response.text()).toBe(409);
  const error = ((await response.json()) as { error: { code: string; missing_kinds: string[] } }).error;
  expect(error.code).toBe("documents_incomplete");
  expect(error.missing_kinds).toEqual(["contract", "insurance_certificate"]);
});
